/* Y2K 千禧年 —— 金属银泡泡，浅蓝紫闪光 */
.t-y2k {
  --bg: #dfe6f2; --bg2: #cdd8ec;
  --surface: rgba(255,255,255,.66); --surface-2: rgba(255,255,255,.9);
  --border: rgba(255,255,255,.9); --border-hover: #7f9cf5;
  --text: #2a2f45; --text-2: #6b7394;
  --accent: #7f9cf5; --accent-2: #f687b3;
  --nav-bg: rgba(223,230,242,.75);
  --font-body: "Inter", -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  --font-head: var(--font-body);
  --radius: 24px; --radius-sm: 99px; --bar-radius: 99px;
  --bg-decor:
    radial-gradient(60% 45% at 80% 6%, rgba(246,135,179,.22), transparent 70%),
    radial-gradient(55% 45% at 10% 90%, rgba(127,156,245,.24), transparent 70%),
    linear-gradient(160deg, #e8eef8 0%, #cdd8ec 100%);
  --shadow: 0 8px 24px rgba(90,110,170,.16), inset 0 1.5px 0 rgba(255,255,255,.95);
  --shadow-hover: 0 14px 36px rgba(127,156,245,.3), inset 0 1.5px 0 rgba(255,255,255,.95);
  --avatar-glow: radial-gradient(circle, rgba(246,135,179,.35), transparent 65%);
}
body.t-y2k .bg-fx {
  background:
    radial-gradient(circle 3px at 15% 25%, #fff 60%, transparent),
    radial-gradient(circle 2px at 80% 15%, #fff 60%, transparent),
    radial-gradient(circle 2.5px at 65% 70%, #fff 60%, transparent),
    radial-gradient(circle 2px at 30% 80%, #fff 60%, transparent),
    radial-gradient(circle 3px at 90% 55%, #fff 60%, transparent),
    radial-gradient(circle 2px at 45% 10%, #fff 60%, transparent);
  animation: y2ksparkle 3.2s ease-in-out infinite;
}
@keyframes y2ksparkle { 0%,100% { opacity: .35 } 50% { opacity: .9 } }
@media (prefers-reduced-motion: reduce) {
  body.t-y2k .bg-fx { animation: none; }
}
body.t-y2k .hero h1 {
  background: linear-gradient(120deg, #7f9cf5 20%, #f687b3 80%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 2px 0 rgba(255,255,255,.8));
}
body.t-y2k .tagline { color: #f687b3; font-weight: 700; }
body.t-y2k .section-tag { background: rgba(255,255,255,.7); box-shadow: inset 0 1.5px 0 #fff, 0 2px 8px rgba(90,110,170,.14); }
body.t-y2k .card, body.t-y2k .post, body.t-y2k .fact, body.t-y2k .contact-card, body.t-y2k .hero-badge {
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
}
body.t-y2k .card.featured { border-color: #f687b3; border-width: 2px; }
body.t-y2k .card.featured::before { background: linear-gradient(90deg, #f687b3, #7f9cf5); }
body.t-y2k .btn { border-radius: 99px; font-weight: 700; }
body.t-y2k .btn-primary {
  background: linear-gradient(180deg, #a8bcf8 0%, #7f9cf5 50%, #6a87e8 100%);
  color: #fff; text-shadow: 0 1px 2px rgba(70,90,160,.4);
  box-shadow: inset 0 1.5px 0 rgba(255,255,255,.7), 0 6px 16px rgba(127,156,245,.4);
}
body.t-y2k .btn-primary:hover { box-shadow: inset 0 1.5px 0 rgba(255,255,255,.7), 0 10px 26px rgba(127,156,245,.55); }
body.t-y2k .btn-ghost { background: rgba(255,255,255,.7); border-color: rgba(255,255,255,.95); box-shadow: inset 0 1.5px 0 #fff, 0 4px 12px rgba(90,110,170,.14); }
body.t-y2k .lang { background: rgba(255,255,255,.8); border-color: rgba(255,255,255,.95); color: #6b7394; }
body.t-y2k .tag { background: rgba(255,255,255,.72); border-color: rgba(255,255,255,.95); box-shadow: inset 0 1px 0 #fff; }
body.t-y2k .bar-track { background: rgba(255,255,255,.7); box-shadow: inset 0 2px 4px rgba(90,110,170,.18); height: 12px; }
body.t-y2k .bar-fill { background: linear-gradient(180deg, #b3c4f9, #7f9cf5); box-shadow: inset 0 1.5px 0 rgba(255,255,255,.6); }
body.t-y2k .bar-row:nth-child(2) .bar-fill { background: linear-gradient(180deg, #f9b8d2, #f687b3); }
body.t-y2k .hero-badge i { background: #f687b3; }
body.t-y2k .stat b { background: linear-gradient(120deg, #7f9cf5, #f687b3); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
body.t-y2k .contact-ico { background: rgba(255,255,255,.85); border-color: rgba(255,255,255,.95); border-radius: 50%; box-shadow: inset 0 1.5px 0 #fff; }
body.t-y2k .contact-ico svg { fill: #7f9cf5; }
body.t-y2k .gallery-link { border-radius: 99px; background: rgba(255,255,255,.7); }
